update_rule.pseudocode:
if day_index == params.policy_start_day:
  policy.mandate_active = True
if policy.mandate_active:
  for each location L of scope params.mandate_scope:
    L.policy_enforcement_level = params.enforcement_strength
  expected_checks = int(params.enforcement_strength * params.enforcement_checks_base)
  for k in 1..expected_checks:
    sample a location L weighted by occupancy
    sample a person i in L
    if i.wearing_mask == 0:
      if Uniform(0,1) < params.enforcement_detect_prob:
        fine = params.fine_amount
        record enforcement action; accumulate cost params.enforcement_unit_cost; collect fine
        with prob params.enforcement_denial_prob, deny entry -> remove i from location and reduce contacts
signals.campaign_intensity = params.campaign_intensity

// Contacts per location per person
for each location type T with share params.location_mix[T]:
  assign persons to locations respecting capacity and schedules
  for each location L of type T:
    compute occupancy and pair contacts per person ~ Poisson(params.contacts_per_person_per_day * params.location_contact_multiplier[T])
    for each contact pair (i,j):
      if (i.health_state == 'I' and j.health_state == 'S') or vice versa:
        eff_prob = params.baseline_transmission_probability_per_contact
        // apply location risk multiplier
        eff_prob *= L.baseline_transmission_risk
        // apply masks
        source_mask = (infectious_person.wearing_mask ? (1 - params.mask_efficacy_source_control) : 1)
        wearer_mask = (susceptible_person.wearing_mask ? (1 - params.mask_efficacy_wearer_protection) : 1)
        p_trans = eff_prob * source_mask * wearer_mask
        if Bernoulli(p_trans): mark susceptible as Exposed and increment new_infections
// Disease progression
for each person i:
  if i.health_state == 'E': i.days_in_state += 1; if i.days_in_state >= params.incubation_period_mean: i.health_state='I'; i.days_in_state=0; i.symptomatic = Bernoulli(params.symptomatic_fraction)
  elif i.health_state == 'I': i.days_in_state += 1; if i.days_in_state >= params.infectious_period_mean: i.health_state='R'; i.days_in_state=0
// Effective Rt
Rt = new_infections_today / max(1, infectious_count_today) * params.generation_time_mean
emit Rt and new infections
